        _call_location_id='%s:%s' % (frame.f_code.co_filename, frame.f_lineno))
    InteractiveShellEmbed.clear_instance()

    if saved_shell_instance is not None:
        cls = type(saved_shell_instance)
        cls.clear_instance()
