    """
    Render text as Markdown

    Example:
        {{ text | render_markdown }}
    """

    value = strip_tags(value)


    schemes = "|".join(settings.ALLOWED_URL_SCHEMES)
    pattern = rf"\[(.+)\]\((?!({schemes})).*:(.+)\)"
