        """
        Read mixed array.

        @rtype: L{pyamf.MixedArray}
        """

        self.stream.read_ulong()

        obj = pyamf.MixedArray()
        self.context.addObject(obj)

        attrs = self.readObjectAttributes(obj)

        for key, value in attrs.iteritems():
            try:
                key = int(key)
            except ValueError:
                pass

            obj[key] = value

