            objType = obj.__class__.__name__.rstrip("I")
            if objType not in linksByType:
                linksByType[objType] = []
            linksByType[objType].append(obj.id.val)
        for linkType, ids in linksByType.items():
            self.conn.deleteObjects(linkType, ids, wait=True)
