            '--pubkey-cert-{type}'.format(type=cert_type), cert_file,
            '--id-attr:{id_attr_name}'.format(id_attr_name=id_attr),
            node_name,
        ]

        if node_id:
            com_list.extend(['--node-id', node_id])

        try:
            (_stdout, stderr, _output) = self._run_xmlsec(com_list, [tmp.name])
