        if isinstance(o, bytes) and not isinstance(o, str):
            o = o.decode('utf-8')
        if isinstance(e, bytes) and not isinstance(e, str):
            e = e.decode('utf-8')


        lastNewLine = o.rfind('\n', 0, len(o)-1)
        if lastNewLine != -1:

            lastLine = o[lastNewLine+1:].strip()

            sys.stdout.write(o[:lastNewLine+1])
        else:

            lastLine = o.strip()

        if e:
            sys.stderr.write(e)

